/**
 * Deterministic E2E fixtures (SPEC §14.5) rendered with the same synthesizer as the benchmark.
 * Output: tests/fixtures/generated/*.wav (git-ignored, regenerated by Playwright's globalSetup).
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { patternById } from '../../src/content/patterns';
import { positionMidi, scaleById, scaleStepSequence } from '../../src/content/scales';
import { songById } from '../../src/content/songs';
import { voicingById } from '../../src/content/voicings';
import { deriveSeed } from '../../src/domain/prng';
import { stringNumber } from '../../src/domain/strings';
import { midiToHz, STANDARD_TUNING } from '../../src/domain/theory';
import { expectedNotes } from '../../src/domain/voicing';
import { rms } from '../../src/dsp/spectrum';
import { renderBacking } from '../../src/dsp/synth/backing';
import { applyMuteEnvelope, type NoteSpec, randomTimbre, renderNote } from '../../src/dsp/synth/note';
import { renderSequence, type SequenceNote } from '../../src/dsp/synth/sequence';
import { normalizeNote, renderStrum } from '../../src/dsp/synth/strum';
import { encodeWav } from '../../src/dsp/wav';
import { openNoteQuestions } from '../../src/exercises/quiz/questions';
import { expandChart } from '../../src/exercises/song/runner';

const OUT_DIR = join(import.meta.dirname, '..', '..', 'tests', 'fixtures', 'generated');
const FS = 48000;

/** Detuning (cents) of each open-string fixture, idx 0 = 6th string. E2E-01 checks the saved δ against it. */
export const OPEN_STRING_DETUNE_CENTS = [4, -3, 6, -5, 2, -7] as const;

function sine(freq: number, seconds: number, sampleRate: number, amplitude: number): Float32Array {
  const out = new Float32Array(Math.round(seconds * sampleRate));
  for (let i = 0; i < out.length; i++) out[i] = amplitude * Math.sin((2 * Math.PI * freq * i) / sampleRate);
  return out;
}

function noteSpec(f0: number, seed: number, durationS: number, muted = false): NoteSpec {
  return {
    model: 'karplus-strong',
    f0,
    sampleRate: FS,
    durationS,
    inharmonicityB: 1e-4,
    muted,
    // Muted strings: −30 dB within 120 ms (the benchmark's Mode A muted condition).
    mutedDecayDb: -30,
    mutedDecayMs: 120,
    fundamentalDb: 0,
    ...randomTimbre(seed),
    t60S: 3,
    seed,
  };
}

function peakNormalize(x: Float32Array, peak = 0.5): Float32Array {
  let max = 0;
  for (let i = 0; i < x.length; i++) max = Math.max(max, Math.abs(x[i]!));
  const g = peak / Math.max(max, 1e-9);
  for (let i = 0; i < x.length; i++) x[i] = x[i]! * g;
  return x;
}

/** One pluck at 0.1 s; muted notes keep the level of a ringing one (normalized before the mute envelope). */
function singlePluck(f0: number, seed: number, muted: boolean, totalS = 1.6): Float32Array {
  const spec = noteSpec(f0, seed, totalS - 0.1, muted);
  const note = renderNote({ ...spec, muted: false });
  normalizeNote(note, FS);
  if (muted) applyMuteEnvelope(note, spec);
  const out = new Float32Array(Math.round(totalS * FS));
  out.set(note.subarray(0, out.length - Math.round(0.1 * FS)), Math.round(0.1 * FS));
  return out;
}

/** E1 fixtures for the C chord (x32010): every played string, the 2nd string muted, and a strum with the
 * x (6th) string ringing. Levels are scaled together so a muted string is not just a quiet one. */
function chordFixtures(): Record<string, Float32Array> {
  const c = voicingById('C');
  const out: Record<string, Float32Array> = {};
  const plucks: Record<string, Float32Array> = {};
  for (const n of expectedNotes(c, STANDARD_TUNING)) {
    plucks[`c-pluck-${stringNumber(n.idx)}.wav`] = singlePluck(n.f0, 2000 + n.idx, false);
    if (n.idx === 4) plucks['c-pluck-2-muted.wav'] = singlePluck(n.f0, 2000 + n.idx, true);
  }
  let max = 0;
  for (const x of Object.values(plucks))
    for (let i = 0; i < x.length; i++) max = Math.max(max, Math.abs(x[i]!));
  for (const [name, x] of Object.entries(plucks)) {
    for (let i = 0; i < x.length; i++) x[i] = (x[i]! * 0.5) / max;
    out[name] = x;
  }
  const ringing = [
    { idx: 0, midi: STANDARD_TUNING.openMidi[0]! },
    ...expectedNotes(c, STANDARD_TUNING).map((n) => ({
      idx: n.idx,
      midi: Math.round(69 + 12 * Math.log2(n.f0 / 440)),
    })),
  ];
  const strum = renderStrum({
    strings: ringing.map(({ idx, midi }) => ({
      idx,
      note: noteSpec(midiToHz(midi), 3000 + idx, 2.2),
      gainDb: 0,
    })),
    direction: 'down',
    spreadMs: 20,
    sampleRate: FS,
  });
  const strumOut = new Float32Array(Math.round(2.5 * FS));
  strumOut.set(strum.signal.subarray(0, strumOut.length - Math.round(0.1 * FS)), Math.round(0.1 * FS));
  out['c-strum-6-ringing.wav'] = peakNormalize(strumOut);
  return out;
}

/** Down strum of a voicing (all played strings), `durationS` long. */
function strumOf(
  voicingId: string,
  seed: number,
  durationS: number,
  direction: 'down' | 'up' = 'down',
): Float32Array {
  const v = voicingById(voicingId);
  return renderStrum({
    strings: expectedNotes(v, STANDARD_TUNING).map((n) => ({
      idx: n.idx,
      note: noteSpec(n.f0, seed * 10 + n.idx, durationS),
      gainDb: 0,
    })),
    direction,
    spreadMs: 18,
    sampleRate: FS,
  }).signal;
}

/** Strums placed at `times` (s); each one is cut by the next (the hand damps when changing). */
function strumSequence(chords: readonly string[], times: readonly number[], totalS: number): Float32Array {
  const out = new Float32Array(Math.round(totalS * FS));
  times.forEach((t, k) => {
    const next = times[k + 1] ?? totalS;
    const strum = strumOf(chords[k % chords.length]!, 4000 + k, Math.min(1.5, next - t));
    const start = Math.round(t * FS);
    for (let i = 0; i < strum.length && start + i < out.length; i++)
      out[start + i] = out[start + i]! + strum[i]!;
  });
  return peakNormalize(out);
}

/** E2E-06: P3 (D - D U - U D U) at 80 BPM, 8 bars of C; the first slot at 0.2 s into the file. */
export const E5_FIXTURE = { patternId: 'P3', bpm: 80, bars: 8, chord: 'C', leadS: 0.2 } as const;

function patternFixture(): Float32Array {
  const slots = ['D', '-', 'D', 'U', '-', 'U', 'D', 'U'] as const;
  const slotS = 60 / E5_FIXTURE.bpm / 2;
  const times: number[] = [];
  const directions: ('down' | 'up')[] = [];
  for (let bar = 0; bar < E5_FIXTURE.bars; bar++)
    slots.forEach((s, i) => {
      if (s === '-') return;
      times.push(E5_FIXTURE.leadS + (bar * slots.length + i) * slotS);
      directions.push(s === 'D' ? 'down' : 'up');
    });
  const totalS = times.at(-1)! + 1.2;
  const out = new Float32Array(Math.round(totalS * FS));
  times.forEach((t, k) => {
    const next = times[k + 1] ?? totalS;
    const strum = strumOf(E5_FIXTURE.chord, 5000 + k, Math.min(1, next - t), directions[k]);
    const start = Math.round(t * FS);
    for (let i = 0; i < strum.length && start + i < out.length; i++)
      out[start + i] = out[start + i]! + strum[i]!;
  });
  return peakNormalize(out);
}

/** E2E-05: A↔D every 1.0 s from 0.5 s, 15 strums = 14 changes (fits the 15 s of a 60 s minute at 0.25×). */
export const E2_FIXTURE = {
  chords: ['A', 'D'],
  times: Array.from({ length: 15 }, (_, k) => 0.5 + k),
  changes: 14,
} as const;

function openStringNote(idx: number, seed: number, durationS: number): Float32Array {
  const f0 = midiToHz(STANDARD_TUNING.openMidi[idx]!) * 2 ** (OPEN_STRING_DETUNE_CENTS[idx]! / 1200);
  const spec: NoteSpec = {
    model: 'karplus-strong',
    f0,
    sampleRate: FS,
    durationS,
    inharmonicityB: 1e-4,
    muted: false,
    mutedDecayDb: 0,
    mutedDecayMs: 120,
    fundamentalDb: 0,
    ...randomTimbre(seed),
    t60S: 3,
    seed,
  };
  const note = renderNote(spec);
  normalizeNote(note, FS);
  return note;
}

/** Plucks of one open string at the given times (s) mixed into `totalS` seconds. */
function plucks(idx: number, timesS: readonly number[], totalS: number, noteS: number): Float32Array {
  const out = new Float32Array(Math.round(totalS * FS));
  timesS.forEach((t, k) => {
    const note = openStringNote(idx, deriveSeed(1000 + idx, `pluck-${k}`), noteS);
    let peak = 0;
    for (let i = 0; i < note.length; i++) peak = Math.max(peak, Math.abs(note[i]!));
    // Peak 0.5: loud and clear, well below the 0.98 clipping guard.
    const gain = 0.5 / Math.max(peak, 1e-9);
    const start = Math.round(t * FS);
    for (let i = 0; i < note.length && start + i < out.length; i++)
      out[start + i] = out[start + i]! + gain * note[i]!;
  });
  return out;
}

/** E2E-16: Em pentatonic step 1 at 80 BPM, five cycles; cycle 5 plays its 6th note a fret too high. */
export const E10_FIXTURE = {
  scaleId: 'em-pent-open',
  step: 1,
  bpm: 80,
  cycles: 5,
  wrongCycle: 4,
  wrongIndex: 5,
  leadS: 0.3,
} as const;

function scaleFixture(): Float32Array {
  const scale = scaleById(E10_FIXTURE.scaleId);
  const order = scaleStepSequence(scale, E10_FIXTURE.step);
  const ioi = 60 / E10_FIXTURE.bpm;
  const notes: SequenceNote[] = [];
  for (let c = 0; c < E10_FIXTURE.cycles; c++) {
    order.forEach((i, k) => {
      const n = scale.notes[i]!;
      const wrong = c === E10_FIXTURE.wrongCycle && k === E10_FIXTURE.wrongIndex;
      const fret = n.fret + (wrong ? 1 : 0);
      const index = c * order.length + k;
      notes.push({
        time: E10_FIXTURE.leadS + index * ioi,
        string: n.string,
        note: noteSpec(
          midiToHz(positionMidi({ string: n.string, fret })),
          deriveSeed(3000, `e10-${index}`),
          2,
        ),
        gainDb: 0,
      });
    });
  }
  const totalS = notes.at(-1)!.time + 1.5;
  return peakNormalize(renderSequence(notes, FS, Math.round(totalS * FS)).signal);
}

/**
 * E2E-17: song s01 (D D A A ×4) at 100 BPM, one strum on every beat 1 from leadS — except bar `silentBar` (not a
 * chord change), so a backing hit counted as the user's strum would show up as a beat-1 hit there. Under
 * speakers the backing bleeds in at `bleedRelDb` on the §14.8 backingBleed scale (−25…−10 dB).
 */
export const SONG_FIXTURE = { songId: 's01', bpm: 100, leadS: 0.3, silentBar: 5, bleedRelDb: -12 } as const;

/**
 * Loopback gain that puts the app's s01 backing `SONG_FIXTURE.bleedRelDb` below the fixture's strums, measured as
 * §14.8 does: the backing's first-event 500 ms RMS against the user's first strum's. The backing is rendered
 * with the song plugin's settings (intro bar + chart, Karplus-Strong, seed 7).
 */
export function songBleedLoopbackGain(): number {
  const song = songById(SONG_FIXTURE.songId);
  const bars = expandChart(song).map((b) => b.chord);
  const backing = renderBacking({
    chords: [bars[0]!, ...bars].map((c) => voicingById(c)),
    pattern: patternById(song.patternId),
    bpm: SONG_FIXTURE.bpm,
    bars: bars.length + 1,
    sampleRate: FS,
    model: 'karplus-strong',
    seed: 7,
  });
  const user = songFixture();
  const lead = Math.round(SONG_FIXTURE.leadS * FS);
  const userRms = rms(user, lead, lead + Math.round(0.5 * FS));
  const backingRms = rms(backing.signal, 0, Math.round(0.5 * FS));
  return (userRms * 10 ** (SONG_FIXTURE.bleedRelDb / 20)) / backingRms;
}

function songFixture(): Float32Array {
  const bars = expandChart(songById(SONG_FIXTURE.songId)).map((b) => b.chord);
  const barS = (4 * 60) / SONG_FIXTURE.bpm;
  const played = bars.flatMap((chord, b) =>
    b === SONG_FIXTURE.silentBar ? [] : [{ chord, time: SONG_FIXTURE.leadS + b * barS }],
  );
  const lastBarEnd = SONG_FIXTURE.leadS + bars.length * barS;
  return strumSequence(
    played.map((p) => p.chord),
    played.map((p) => p.time),
    lastBarEnd + 1,
  );
}

/** E2E-21: the first question of a Q3 strings-6/5 "pluck" run with this seed, played as one sustained note. */
export const Q3_FIXTURE = { seed: 777, scope: 'strings65' } as const;

export function q3FixturePosition(): { idx: number; fret: number } {
  const q = openNoteQuestions(Q3_FIXTURE.seed, 'pluck', 1, [], Q3_FIXTURE.scope)[0]!;
  return { idx: q.prompt.idx, fret: q.prompt.fret };
}

function q3Fixture(): Float32Array {
  const { idx, fret } = q3FixturePosition();
  const f0 = midiToHz(STANDARD_TUNING.openMidi[idx]! + fret);
  const note = renderNote(noteSpec(f0, 4242, 3));
  normalizeNote(note, FS);
  const out = new Float32Array(Math.round(3.5 * FS));
  out.set(note, Math.round(0.2 * FS));
  return peakNormalize(out);
}

function main(): void {
  mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync(join(OUT_DIR, 'spike-sine-440.wav'), encodeWav(sine(440, 2, FS, 0.25), FS));
  // Chrome --use-file-for-fake-audio-capture input (silence lead-in, then a tone).
  const capture = new Float32Array(FS * 6);
  capture.set(sine(196, 4, FS, 0.3), FS);
  writeFileSync(join(OUT_DIR, 'fake-capture.wav'), encodeWav(capture, FS));
  for (let idx = 0; idx < STANDARD_TUNING.openMidi.length; idx++) {
    const n = stringNumber(idx);
    // Tuning: one sustained pluck. Templates: three plucks 0.9 s apart.
    writeFileSync(join(OUT_DIR, `open-${n}.wav`), encodeWav(plucks(idx, [0.1], 2.5, 2.4), FS));
    writeFileSync(join(OUT_DIR, `open3-${n}.wav`), encodeWav(plucks(idx, [0.1, 1.0, 1.9], 2.8, 0.9), FS));
  }
  for (const [name, signal] of Object.entries(chordFixtures()))
    writeFileSync(join(OUT_DIR, name), encodeWav(signal, FS));
  writeFileSync(
    join(OUT_DIR, 'e2-a-d-alternating.wav'),
    encodeWav(strumSequence(E2_FIXTURE.chords, E2_FIXTURE.times, 16), FS),
  );
  writeFileSync(join(OUT_DIR, 'e5-p3-80.wav'), encodeWav(patternFixture(), FS));
  writeFileSync(join(OUT_DIR, 'e10-em-pent-s1-80.wav'), encodeWav(scaleFixture(), FS));
  writeFileSync(join(OUT_DIR, 'song-s01-100-beat1.wav'), encodeWav(songFixture(), FS));
  writeFileSync(join(OUT_DIR, 'q3-strings65.wav'), encodeWav(q3Fixture(), FS));
  console.log(`fixtures written to ${OUT_DIR}`);
}

if (process.argv[1]?.endsWith('generate.ts')) main();
